CREATE TABLE Discipline ( nom_discipline VARCHAR(40) PRIMARY KEY, mode_pratique  VARCHAR(10) );
CREATE TABLE Equipe ( nom_equipe VARCHAR(50) PRIMARY KEY, nom_discipline VARCHAR(40) NOT NULL, FOREIGN KEY (nom_discipline) REFERENCES Discipline(nom_discipline) ON DELETE CASCADE ON UPDATE CASCADE );
CREATE TABLE Modele_capteur ( nom_modele VARCHAR(40) PRIMARY KEY, type_capteur VARCHAR(30));
CREATE TABLE Test_physique ( nom_test VARCHAR(40) PRIMARY KEY, unite_resultat VARCHAR(10));
CREATE TABLE Intervenant ( id_intervenant SMALLINT PRIMARY KEY, fonction VARCHAR(40), nom_intervenant VARCHAR(30), id_intervenant_superviseur SMALLINT NULL, FOREIGN KEY (id_intervenant_superviseur) REFERENCES Intervenant(id_intervenant) ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE Athlete ( numero_licence VARCHAR(10) PRIMARY KEY, nom_athlete VARCHAR(30), prenom_athlete VARCHAR(30), date_naissance DATE, sexe CHAR(1), taille SMALLINT, nom_discipline VARCHAR(40) NOT NULL, FOREIGN KEY (nom_discipline) REFERENCES Discipline(nom_discipline) ON DELETE CASCADE ON UPDATE CASCADE );
CREATE TABLE Capteur ( numero_serie VARCHAR(12) PRIMARY KEY, date_etalonnage DATE, nom_modele VARCHAR(40) NOT NULL, FOREIGN KEY (nom_modele) REFERENCES Modele_capteur(nom_modele) ON DELETE CASCADE ON UPDATE CASCADE );
CREATE TABLE Seance ( code_seance VARCHAR(8) PRIMARY KEY, date_heure_debut DATETIME, duree SMALLINT, type_seance VARCHAR(15), nom_lieu VARCHAR(50), nom_equipe VARCHAR(50) NULL, FOREIGN KEY (nom_equipe) REFERENCES Equipe(nom_equipe) ON DELETE SET NULL ON UPDATE CASCADE );
CREATE TABLE Blessure (numero_licence VARCHAR(10), numero_blessure TINYINT, date_blessure DATE, zone_corps VARCHAR(40), gravite VARCHAR(10), date_reprise DATE, code_seance VARCHAR(8) NULL, id_intervenant SMALLINT NOT NULL, PRIMARY KEY (numero_licence, numero_blessure), FOREIGN KEY (numero_licence) REFERENCES Athlete(numero_licence) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (code_seance) REFERENCES Seance(code_seance) ON DELETE SET NULL ON UPDATE CASCADE, FOREIGN KEY (id_intervenant) REFERENCES Intervenant(id_intervenant) ON DELETE CASCADE ON UPDATE CASCADE );
CREATE TABLE Appartenir ( numero_licence VARCHAR(10), nom_equipe VARCHAR(50), poste_occupe VARCHAR(30), date_arrivee DATE, PRIMARY KEY (numero_licence, nom_equipe), FOREIGN KEY (numero_licence) REFERENCES Athlete(numero_licence) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (nom_equipe) REFERENCES Equipe(nom_equipe) ON DELETE CASCADE ON UPDATE CASCADE );
CREATE TABLE Participer ( numero_licence VARCHAR(10), code_seance VARCHAR(8), distance_totale INT, vitesse_max DECIMAL(3,1), fc_moyenne SMALLINT, fc_max SMALLINT, charge_entrainement DECIMAL(6,1), PRIMARY KEY (numero_licence, code_seance), FOREIGN KEY (numero_licence) REFERENCES Athlete(numero_licence) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (code_seance) REFERENCES Seance(code_seance) ON DELETE CASCADE ON UPDATE CASCADE );
CREATE TABLE Encadrer ( code_seance VARCHAR(8), id_intervenant SMALLINT, PRIMARY KEY (code_seance, id_intervenant), FOREIGN KEY (code_seance) REFERENCES Seance(code_seance) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (id_intervenant) REFERENCES Intervenant(id_intervenant) ON DELETE CASCADE ON UPDATE CASCADE );
CREATE TABLE Porter ( numero_licence VARCHAR(10), numero_serie VARCHAR(12), code_seance VARCHAR(8), PRIMARY KEY (numero_licence, numero_serie, code_seance), FOREIGN KEY (numero_licence) REFERENCES Athlete(numero_licence) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (numero_serie) REFERENCES Capteur(numero_serie) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (code_seance) REFERENCES Seance(code_seance) ON DELETE CASCADE ON UPDATE CASCADE );
CREATE TABLE Passer ( numero_licence VARCHAR(10), code_seance VARCHAR(8), nom_test VARCHAR(40), resultat_test DECIMAL(6,2), PRIMARY KEY (numero_licence, code_seance, nom_test), FOREIGN KEY (numero_licence) REFERENCES Athlete(numero_licence) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (code_seance) REFERENCES Seance(code_seance) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (nom_test) REFERENCES Test_physique(nom_test) ON DELETE CASCADE ON UPDATE CASCADE );
